  {
    "name": "Primary CTA Button (Pill Yellow)",
    "role": "Main conversion actions — 'Iniciar gratis', 'Iniciar prueba gratis'",
    "description": "Background #ffe01b, text #231e15, border 1px solid #231e15 (via box-shadow rgb(35,30,21) 0 0 0 1px), border-radius 26px, padding 12px 24px. Graphik Web 500 at 16px. The yellow fill with dark border creates a physical 'printed label' impression — the stroke is what makes it feel tactile rather than digital."
  },
  {
    "name": "Ghost Navigation Button",
    "role": "Secondary actions like 'Inicia sesión', dropdown triggers",
    "description": "Background transparent, text #231e15, border 1px solid #231e15 (via box-shadow), border-radius 3px, padding 8px. Graphik Web 400 at 14px. The near-zero radius and transparent fill make these nearly invisible alongside the yellow CTA — intentional hierarchy."
  },
  {
    "name": "Arrow Link (Inline CTA)",
    "role": "Section-level 'learn more' navigation — 'Aprende sobre el marketing por SMS →'",
    "description": "Text color #231e15 or #ffffff on dark backgrounds. Graphik Web 500 at 16px. Paired with a circular yellow arrow badge (26px diameter, #ffe01b background, border-radius 32px). On hover, background hint rgba(255,224,27,0.65) appears under text — a yellow wash rather than underline."
  },
  {
    "name": "Feature Card (Dark Section)",
    "role": "3-column feature grid cards on #231e15 backgrounds",
    "description": "Background transparent (rgba(0,0,0,0)), no border, no shadow, border-radius 0px, no padding. Image thumbnail at top (border-radius 10px), heading in Means Web 300 at 24px white, body in Graphik Web 400 at 16px rgba(255,255,255,0.65). Cards are pure content containers with no visual frame — the dark section background is the container."
  },
  {
    "name": "Elevated White Card",
    "role": "Pricing widget, form containers that float over backgrounds",
    "description": "Background #ffffff, border-radius 0px, box-shadow rgba(35,30,21,0.15) 0px 0px 20px 3px, padding 24px 16px. The warm-tinted shadow (not blue-gray) keeps elevation on-brand. Zero radius on white card creates a printed invoice feel."
  },
  {
    "name": "Rounded Content Card",
    "role": "Product screenshot previews, integration tiles",
    "description": "Background #ffffff or #f5f5f5, border-radius 10px, no shadow, padding 8px. Graphik Web 400 at 13-14px. Used to frame UI screenshots and app logos — the 10px radius is the maximum curvature in the system outside pill buttons."
  },
  {
    "name": "Dark Badge / Pill Tag",
    "role": "Labels like 'Prueba sin riesgo', section labels",
    "description": "Background #231e15, text #ffffff, border-radius 8px, padding 4px 12px. Graphik Web 500 at 13px. The near-black fill mirrors the headline color — tags feel stamped, not digital."
  },
  {
    "name": "Underline Input Field",
    "role": "Forms, contact inputs, newsletter signup",
    "description": "Background transparent, border-radius 0px, border-bottom 1px solid #231e15 (or #000000), text #231e15, padding 8px 0px. No visible side or top borders — a ruled-line aesthetic that matches the editorial print vocabulary."
  },
  {
    "name": "Announcement Bar",
    "role": "Top-of-page promotional strip",
    "description": "Background #231e15, text #ffffff at 13px Graphik Web 400, centered. Link text in #ffe01b or underlined white. Full-width, 42px tall. The bar uses the same near-black as body text — continuity without a competing color."
  },
  {
    "name": "Sticky Navigation Bar",
    "role": "Primary site navigation",
    "description": "Background #ffffff, height 68px, bottom border none. Mailchimp wordmark left, nav links in Graphik Web 400 16px #231e15 with chevrons for dropdowns, phone number right, then ghost button 'Inicia sesión', then pill yellow 'Iniciar gratis'. Max contrast between ghost and filled buttons enforces single primary action."
  },
  {
    "name": "Pricing Tier Widget",
    "role": "Plan selection with contact slider and CTA",
    "description": "White elevated card (box-shadow rgba(35,30,21,0.15) 0 0 20px 3px), padding 24px. Plan name in Means Web 300 32px #231e15, price in Means Web 300 48px #231e15 with -1.01px letter-spacing. Radio inputs with #231e15 accent. CTA uses Primary Pill Yellow Button component. Border-radius 0px on the card itself."
  }
